import React from 'react';
import { Icon } from '../icons/Icon.jsx';
const CSS = `
.ef-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;border:1px solid transparent;border-radius:var(--radius-sm);font-family:var(--font-sans);font-weight:var(--weight-semibold);cursor:pointer;white-space:nowrap;user-select:none;transition:background var(--dur-fast) var(--ease-out),border-color var(--dur-fast) var(--ease-out),color var(--dur-fast) var(--ease-out),box-shadow var(--dur-fast) var(--ease-out),transform var(--dur-med) var(--ease-spring)}
.ef-btn:hover,.ef-btn:focus,.ef-btn:visited{text-decoration:none}
.ef-btn:focus-visible{outline:none;box-shadow:var(--focus-ring)}
.ef-btn:active:not(:disabled){transform:scale(.985)}
.ef-btn:disabled{opacity:.45;cursor:not-allowed}
.ef-btn--sm{height:var(--control-h-sm);padding:0 10px;font-size:var(--text-sm)}
.ef-btn--md{height:var(--control-h-md);padding:0 14px;font-size:var(--text-md)}
.ef-btn--lg{height:var(--control-h-lg);padding:0 20px;font-size:var(--text-lg)}
.ef-btn--xs{height:28px;padding:0 9px;font-size:var(--text-xs);gap:6px}
.ef-btn--icon,.ef-btn--icon-md{width:var(--control-h-md);height:var(--control-h-md);padding:0}
.ef-btn--icon-xs{width:24px;height:24px;padding:0}
.ef-btn--icon-sm{width:var(--control-h-sm);height:var(--control-h-sm);padding:0}
.ef-btn--icon-lg{width:var(--control-h-lg);height:var(--control-h-lg);padding:0}
.ef-btn--primary{background:var(--accent);color:var(--accent-contrast)}
.ef-btn--primary:hover:not(:disabled){background:var(--accent-hover)}
.ef-btn--primary:active:not(:disabled){background:var(--accent-active)}
.ef-btn--secondary{background:transparent;color:var(--text-primary);border-color:var(--border-strong)}
.ef-btn--secondary:hover:not(:disabled){background:var(--surface-sunken)}
.ef-btn--ghost{background:transparent;color:var(--text-secondary)}
.ef-btn--ghost:hover:not(:disabled){background:var(--surface-sunken);color:var(--text-primary)}
.ef-btn--danger{background:var(--danger-600);color:var(--danger-contrast)}
.ef-btn--danger:hover:not(:disabled){background:var(--danger-700)}
.ef-btn--brand{background:var(--brand-700);color:var(--text-on-brand)}
.ef-btn--brand:hover:not(:disabled){background:var(--brand-800)}
.ef-btn--outline{background:transparent;color:var(--text-primary);border-color:var(--border-strong)}
.ef-btn--outline:hover:not(:disabled){background:var(--surface-sunken)}
.ef-btn--destructive{background:var(--danger-600);color:var(--danger-contrast)}
.ef-btn--destructive:hover:not(:disabled){background:var(--danger-700)}
.ef-btn--link{height:auto;padding:0;background:transparent;color:var(--text-link);text-underline-offset:4px}
.ef-btn--link:hover:not(:disabled){color:var(--text-link-hover);text-decoration:none}
@keyframes ef-spin{to{transform:rotate(360deg)}}
.ef-btn__spin{display:inline-flex;animation:ef-spin .7s linear infinite}
`;
/**
 * Put a component's CSS in the document, inside the `meridian` cascade layer.
 *
 * THE LAYER IS THE POINT. This appends a <style> at runtime, so it always
 * lands after whatever stylesheet the app shipped, and at equal specificity
 * later wins. Consumer applications otherwise have to double their selectors
 * (`.hide-sm.hide-sm`) because a one-class utility lost to
 * `.ef-badge { display: inline-flex }`, and Meridian restates radii and colours
 * to get its own back. A design system that has to be out-specified by its
 * consumers is not a foundation, it is a competitor.
 *
 * An unlayered rule beats a layered one no matter the order or the
 * specificity, so app CSS now wins by default and meridian is the floor it
 * stands on. Products can stop fighting; the workarounds above can go.
 *
 * Note this changes precedence for pages that shipped before it. Anywhere an
 * app rule accidentally collided with a component rule and lost, it now wins.
 * That is the intended direction, but it is a real change and worth looking at
 * a page or two after upgrading.
 */
export function injectEfCss(id, text) {
  if (typeof document === 'undefined' || document.getElementById(id)) return;
  const s = document.createElement('style');
  s.id = id;
  s.textContent = `@layer meridian{${text}}`;
  document.head.appendChild(s);
}
/**
 * Format a number as a CSS percentage that survives server rendering.
 *
 * A bare `value + '%'` writes every digit JavaScript has: `1/3 * 100` becomes
 * `33.33333333333333%`. Browsers keep roughly six significant figures when they
 * parse an inline style, so the DOM reads back `33.3333%`, and React's
 * hydration check compares its own 16-digit string against the browser's
 * truncated one and reports a mismatch on every affected element. The bars in
 * Player, the fill in UsageMeter and the columns in BarChart all hit this.
 *
 * Rounding to three decimals stays well inside what the parser preserves and is
 * far below one pixel at any realistic size. Number-to-string drops trailing
 * zeros on its own, which matters: `33.300%` would be normalised to `33.3%` and
 * reintroduce the very mismatch this avoids.
 *
 * Lowercase, so it stays an internal helper rather than part of the public
 * namespace.
 */
export function cssPct(value) {
  return (Math.round(value * 1000) / 1000) + '%';
}
/**
 * Point several refs at one node.
